1	// Event signup form — submission logic
2	//
3	// localStorage への永続化 + 二重送信防止 + submit handler 構築。
4	// validation は src/validation.js の純関数を経由するだけで、 ここでは行わない。
5	
6	import { validateForm, hasErrors } from './validation.js';
7	
8	export const STORAGE_KEY = 'pev-sample-submissions';
9	
10	export function loadSubmissions(storage) {
11	  const raw = storage.getItem(STORAGE_KEY);
12	  if (!raw) return [];
13	  try {
14	    const parsed = JSON.parse(raw);
15	    return Array.isArray(parsed) ? parsed : [];
16	  } catch {
17	    return [];
18	  }
19	}
20	
21	export function saveSubmission(storage, submission) {
22	  const all = loadSubmissions(storage);
23	  const entry = { ...submission, submittedAt: new Date().toISOString() };
24	  all.push(entry);
25	  storage.setItem(STORAGE_KEY, JSON.stringify(all));
26	  return entry;
27	}
28	
29	// async simulate (mock API)。 dog food task で実 fetch 化を依頼するときに差し替えやすい形にしておく。
30	export function submitWithDelay(storage, submission, delayMs = 0) {
31	  return new Promise((resolve) => {
32	    setTimeout(() => {
33	      const entry = saveSubmission(storage, submission);
34	      resolve(entry);
35	    }, delayMs);
36	  });
37	}
38	
39	// 二重送信防止 + validation を組み込んだ submit handler を返す。
40	// UI 側は handleSubmit を form の submit に bind するだけ。
41	export function buildSubmitHandler({
42	  getFormData,
43	  setErrors,
44	  setSubmitting,
45	  onSuccess,
46	  storage,
47	  delayMs = 300,
48	}) {
49	  let submitting = false;
50	  return async function handleSubmit(event) {
51	    event.preventDefault();
52	    if (submitting) return;
53	    const data = getFormData();
54	    const errors = validateForm(data);
55	    setErrors(errors);
56	    if (hasErrors(errors)) return;
57	    submitting = true;
58	    setSubmitting(true);
59	    try {
60	      const entry = await submitWithDelay(storage, data, delayMs);
61	      onSuccess(entry);
62	    } finally {
63	      submitting = false;
64	      setSubmitting(false);
65	    }
66	  };
67	}
