68	<body>
69	  <h1>イベント参加申し込み</h1>
70	  <p class="lead">PEV harness sample — 申し込みフォーム fixture (dog food 用)</p>
71	
72	  <form id="signup-form" novalidate>
73	    <div class="field">
74	      <label for="name">氏名<span class="required-mark" aria-hidden="true">*</span></label>
75	      <input id="name" name="name" type="text" autocomplete="name" required aria-required="true" aria-describedby="name-error">
76	      <div id="name-error" class="error" role="alert" aria-live="polite"></div>
77	    </div>
78	
79	    <div class="field">
80	      <label for="email">メールアドレス<span class="required-mark" aria-hidden="true">*</span></label>
81	      <input id="email" name="email" type="email" autocomplete="email" required aria-required="true" aria-describedby="email-error">
82	      <div id="email-error" class="error" role="alert" aria-live="polite"></div>
83	    </div>
84	
85	    <div class="field">
86	      <label for="phone">電話番号 (任意)</label>
87	      <input id="phone" name="phone" type="tel" autocomplete="tel" aria-describedby="phone-error" placeholder="090-1234-5678">
88	      <div id="phone-error" class="error" role="alert" aria-live="polite"></div>
89	    </div>
90	
91	    <div class="field">
92	      <label for="plan">参加プラン<span class="required-mark" aria-hidden="true">*</span></label>
93	      <select id="plan" name="plan" required aria-required="true" aria-describedby="plan-error">
94	        <option value="">選択してください</option>
95	        <option value="standard">スタンダード</option>
96	        <option value="premium">プレミアム</option>
97	        <option value="student">学生</option>
98	      </select>
99	      <div id="plan-error" class="error" role="alert" aria-live="polite"></div>
100	    </div>
101	
102	    <div class="field agreement">
103	      <input id="agreement" name="agreement" type="checkbox" aria-describedby="agreement-error">
104	      <label for="agreement">利用規約に同意します<span class="required-mark" aria-hidden="true">*</span></label>
105	    </div>
106	    <div id="agreement-error" class="error" role="alert" aria-live="polite"></div>
107	
108	    <button id="submit-btn" type="submit">申し込む</button>
109	  </form>
110	
111	  <div id="success" role="status" aria-live="polite" hidden></div>
112	
113	  <script type="module">
114	    import { buildSubmitHandler } from './src/form.js';
115	
116	    const form = document.getElementById('signup-form');
117	    const submitBtn = document.getElementById('submit-btn');
118	    const success = document.getElementById('success');
119	
120	    const fields = ['name', 'email', 'phone', 'plan', 'agreement'];
121	
122	    function getFormData() {
123	      return {
124	        name: document.getElementById('name').value,
125	        email: document.getElementById('email').value,
126	        phone: document.getElementById('phone').value,
127	        plan: document.getElementById('plan').value,
128	        agreement: document.getElementById('agreement').checked,
129	      };
130	    }
131	
132	    function setErrors(errors) {
133	      for (const f of fields) {
134	        const el = document.getElementById(`${f}-error`);
135	        if (!el) continue;
136	        el.textContent = errors[f] ?? '';
137	      }
138	    }
139	
140	    function setSubmitting(flag) {
141	      submitBtn.disabled = flag;
142	      submitBtn.textContent = flag ? '送信中…' : '申し込む';
143	    }
144	
145	    function onSuccess(entry) {
146	      success.hidden = false;
147	      success.textContent = `申し込みを受け付けました (${entry.name} 様)`;
148	      form.reset();
149	      setErrors({ name: null, email: null, phone: null, plan: null, agreement: null });
150	    }
151	
152	    const handleSubmit = buildSubmitHandler({
153	      getFormData,
154	      setErrors,
155	      setSubmitting,
156	      onSuccess,
157	      storage: window.localStorage,
158	      delayMs: 300,
159	    });
160	
161	    form.addEventListener('submit', handleSubmit);
162	
163	    // Hide success message as soon as the user starts editing again.
164	    form.addEventListener('input', () => {
165	      if (!success.hidden) success.hidden = true;
166	    });
167	  </script>
168	</body>
169	</html>
