1	import { test, expect, type Page, type ConsoleMessage } from '@playwright/test';
2	
3	// Seed test — Playwright Agents (planner/generator) の前提として必須。
4	// 環境初期化 + 生成 test の参考例として機能する。
5	// pev-bootstrap-playwright skill (v1.4) が template として置く。
6	// v1.6: DRY pattern (test.beforeEach + console listener fixture) を seed に組み込み、
7	//       Generator/Healer が新規 test を書くときの reference として活用する。
8	// v1.7.1+: sample-project は「イベント申し込みフォーム」に刷新済。 form 系の test を
9	//          典型 fixture として置いておく。
10	
11	const consoleErrors: string[] = [];
12	
13	test.beforeEach(async ({ page }) => {
14	  consoleErrors.length = 0;
15	  page.on('console', (msg: ConsoleMessage) => {
16	    if (msg.type() === 'error') consoleErrors.push(msg.text());
17	  });
18	  page.on('pageerror', (err: Error) => {
19	    consoleErrors.push(`pageerror: ${err.message}`);
20	  });
21	});
