23	async function goHome(page: Page) {
24	  await page.goto('/');
25	  await expect(page.locator('h1')).toBeVisible();
26	  // localStorage は test ごとに分離する: 前の test の submission が残らないように。
27	  await page.evaluate(() => localStorage.clear());
28	}
29	
30	async function fillValidForm(page: Page) {
31	  await page.fill('#name', '山田太郎');
32	  await page.fill('#email', 'taro@example.com');
33	  await page.selectOption('#plan', 'standard');
34	  await page.check('#agreement');
35	}
36	
37	test('homepage loads with form fields visible', async ({ page }) => {
38	  await goHome(page);
39	  await expect(page).toHaveTitle('PEV harness sample — event signup');
40	  await expect(page.locator('#name')).toBeVisible();
41	  await expect(page.locator('#email')).toBeVisible();
42	  await expect(page.locator('#phone')).toBeVisible();
43	  await expect(page.locator('#plan')).toBeVisible();
44	  await expect(page.locator('#agreement')).toBeVisible();
45	  await expect(page.locator('#submit-btn')).toBeVisible();
46	});
47	
48	test('valid submit: success message appears and form resets', async ({ page }) => {
49	  await goHome(page);
50	  await fillValidForm(page);
51	  await page.click('#submit-btn');
52	  await expect(page.locator('#success')).toBeVisible();
53	  await expect(page.locator('#success')).toContainText('申し込みを受け付けました');
54	  await expect(page.locator('#name')).toHaveValue('');
55	  await expect(page.locator('#email')).toHaveValue('');
56	});
57	
58	test('missing required field shows error and blocks submit', async ({ page }) => {
59	  await goHome(page);
60	  await page.fill('#name', '山田');
61	  await page.selectOption('#plan', 'premium');
62	  await page.check('#agreement');
63	  await page.click('#submit-btn');
64	  await expect(page.locator('#email-error')).toContainText('メールアドレスは必須です');
65	  await expect(page.locator('#success')).toBeHidden();
66	});
67	
68	test('invalid email format shows error', async ({ page }) => {
69	  await goHome(page);
70	  await page.fill('#name', '山田');
71	  await page.fill('#email', 'not-an-email');
72	  await page.selectOption('#plan', 'standard');
73	  await page.check('#agreement');
74	  await page.click('#submit-btn');
75	  await expect(page.locator('#email-error')).toContainText('形式が正しくありません');
76	});
77	
78	test('double submit prevention: rapid clicks produce single submission', async ({ page }) => {
79	  await goHome(page);
80	  await fillValidForm(page);
81	  await Promise.all([
82	    page.click('#submit-btn'),
83	    page.click('#submit-btn', { force: true }).catch(() => {}),
84	  ]);
85	  await expect(page.locator('#success')).toBeVisible();
86	  const count = await page.evaluate(() => {
87	    const raw = localStorage.getItem('pev-sample-submissions');
88	    return raw ? (JSON.parse(raw) as unknown[]).length : 0;
89	  });
90	  expect(count).toBe(1);
91	});
